/* ============================================
   GlobalStone Design System
   ============================================ */

/* --- 1. Primitive Tokens (OKLCH Colors) --- */
:root {
  /* Primary: Deep Forest Green */
  --color-green-50:  oklch(97% 0.01 165);
  --color-green-100: oklch(93% 0.03 165);
  --color-green-200: oklch(85% 0.06 165);
  --color-green-300: oklch(75% 0.10 165);
  --color-green-400: oklch(62% 0.14 165);
  --color-green-500: oklch(50% 0.12 165);
  --color-green-600: oklch(40% 0.10 165);
  --color-green-700: oklch(32% 0.08 165);
  --color-green-800: oklch(25% 0.06 165);
  --color-green-900: oklch(18% 0.04 165);

  /* Secondary: Dark Teal */
  --color-teal-50:  oklch(97% 0.01 195);
  --color-teal-100: oklch(92% 0.03 195);
  --color-teal-200: oklch(82% 0.06 195);
  --color-teal-300: oklch(70% 0.10 195);
  --color-teal-400: oklch(58% 0.12 195);
  --color-teal-500: oklch(46% 0.10 195);
  --color-teal-600: oklch(36% 0.08 195);
  --color-teal-700: oklch(28% 0.06 195);
  --color-teal-800: oklch(20% 0.04 195);
  --color-teal-900: oklch(14% 0.03 195);

  /* Neutral: Cool Grays */
  --color-gray-50:  oklch(98% 0.005 250);
  --color-gray-100: oklch(95% 0.01 250);
  --color-gray-200: oklch(90% 0.015 250);
  --color-gray-300: oklch(82% 0.02 250);
  --color-gray-400: oklch(70% 0.02 250);
  --color-gray-500: oklch(58% 0.02 250);
  --color-gray-600: oklch(46% 0.02 250);
  --color-gray-700: oklch(34% 0.015 250);
  --color-gray-800: oklch(22% 0.01 250);
  --color-gray-900: oklch(12% 0.005 250);

  /* Accent: Warm Gold */
  --color-gold-50:  oklch(97% 0.02 85);
  --color-gold-100: oklch(93% 0.04 85);
  --color-gold-200: oklch(87% 0.07 85);
  --color-gold-300: oklch(80% 0.10 85);
  --color-gold-400: oklch(73% 0.13 85);
  --color-gold-500: oklch(66% 0.14 85);
  --color-gold-600: oklch(56% 0.12 85);
  --color-gold-700: oklch(46% 0.10 85);

  /* --- 2. Semantic Tokens --- */
  --color-primary: var(--color-green-700);
  --color-primary-dark: var(--color-green-800);
  --color-primary-light: var(--color-green-600);
  --color-secondary: var(--color-teal-800);
  --color-accent: var(--color-gold-500);
  --color-accent-hover: var(--color-gold-600);

  --color-text-primary: var(--color-gray-900);
  --color-text-secondary: var(--color-gray-600);
  --color-text-muted: var(--color-gray-500);
  --color-text-inverse: var(--color-gray-50);

  --color-bg-primary: #ffffff;
  --color-bg-secondary: var(--color-gray-50);
  --color-bg-tertiary: var(--color-gray-100);
  --color-bg-dark: var(--color-green-900);
  --color-bg-dark-alt: var(--color-teal-900);

  --color-border: var(--color-gray-200);
  --color-border-light: var(--color-gray-100);

  /* --- 3. Typography --- */
  --font-heading: "DM Serif Display", Georgia, "Times New Roman", serif;
  --font-body: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;

  --text-xs: clamp(0.75rem, 0.7rem + 0.2vw, 0.875rem);
  --text-sm: clamp(0.875rem, 0.8rem + 0.25vw, 1rem);
  --text-base: clamp(1rem, 0.9rem + 0.3vw, 1.125rem);
  --text-lg: clamp(1.125rem, 1rem + 0.4vw, 1.25rem);
  --text-xl: clamp(1.25rem, 1.1rem + 0.5vw, 1.5rem);
  --text-2xl: clamp(1.5rem, 1.2rem + 0.8vw, 2rem);
  --text-3xl: clamp(1.875rem, 1.4rem + 1.2vw, 2.5rem);
  --text-4xl: clamp(2.25rem, 1.5rem + 2vw, 3.5rem);
  --text-5xl: clamp(2.75rem, 1.8rem + 3vw, 4.5rem);
  --text-6xl: clamp(3.5rem, 2rem + 4vw, 6rem);

  --leading-tight: 1.1;
  --leading-snug: 1.25;
  --leading-normal: 1.5;
  --leading-relaxed: 1.65;

  --tracking-tight: -0.02em;
  --tracking-normal: 0;
  --tracking-wide: 0.05em;
  --tracking-wider: 0.1em;

  /* --- 4. Spacing --- */
  --space-1: 0.25rem;
  --space-2: 0.5rem;
  --space-3: 0.75rem;
  --space-4: 1rem;
  --space-5: 1.25rem;
  --space-6: 1.5rem;
  --space-8: 2rem;
  --space-10: 2.5rem;
  --space-12: 3rem;
  --space-16: 4rem;
  --space-20: 5rem;
  --space-24: 6rem;
  --space-32: 8rem;
  --space-40: 10rem;

  /* --- 5. Layout --- */
  --container-max: 1280px;
  --container-narrow: 768px;
  --container-wide: 1440px;

  --radius-sm: 2px;
  --radius-md: 4px;
  --radius-lg: 8px;
  --radius-xl: 12px;

  --shadow-sm: 0 1px 2px 0 oklch(0% 0 0 / 0.05);
  --shadow-md: 0 4px 6px -1px oklch(0% 0 0 / 0.07), 0 2px 4px -2px oklch(0% 0 0 / 0.05);
  --shadow-lg: 0 10px 15px -3px oklch(0% 0 0 / 0.08), 0 4px 6px -4px oklch(0% 0 0 / 0.05);
  --shadow-xl: 0 20px 25px -5px oklch(0% 0 0 / 0.08), 0 8px 10px -6px oklch(0% 0 0 / 0.05);

  --transition-fast: 150ms ease;
  --transition-base: 250ms ease;
  --transition-slow: 400ms ease;

  --header-height: 72px;
}

/* ============================================
   Reset & Base
   ============================================ */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-body);
  font-size: var(--text-base);
  line-height: var(--leading-normal);
  color: var(--color-text-primary);
  background-color: var(--color-bg-primary);
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

a {
  color: inherit;
  text-decoration: none;
}

ul, ol {
  list-style: none;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
}

/* ============================================
   Typography
   ============================================ */
h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  font-weight: 400;
  line-height: var(--leading-tight);
  letter-spacing: var(--tracking-tight);
  color: var(--color-text-primary);
}

h1 { font-size: var(--text-5xl); }
h2 { font-size: var(--text-4xl); }
h3 { font-size: var(--text-3xl); }
h4 { font-size: var(--text-2xl); }
h5 { font-size: var(--text-xl); }
h6 { font-size: var(--text-lg); }

p {
  color: var(--color-text-secondary);
  line-height: var(--leading-relaxed);
}

/* ============================================
   Layout Utilities
   ============================================ */
.container {
  width: 100%;
  max-width: var(--container-max);
  margin: 0 auto;
  padding-left: var(--space-6);
  padding-right: var(--space-6);
}

.container-narrow {
  max-width: var(--container-narrow);
}

.container-wide {
  max-width: var(--container-wide);
}

.section {
  padding-top: var(--space-24);
  padding-bottom: var(--space-24);
}

.section-sm {
  padding-top: var(--space-16);
  padding-bottom: var(--space-16);
}

.section-lg {
  padding-top: var(--space-32);
  padding-bottom: var(--space-32);
}

/* ============================================
   Header & Navigation
   ============================================ */
.site-header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  height: var(--header-height);
  background: rgba(255, 255, 255, 0.96);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--color-border-light);
  transition: box-shadow var(--transition-base);
}

.site-header.scrolled {
  box-shadow: var(--shadow-md);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 100%;
}

.logo {
  font-family: var(--font-heading);
  font-size: var(--text-2xl);
  color: var(--color-primary);
  letter-spacing: var(--tracking-tight);
  white-space: nowrap;
}

.logo span {
  color: var(--color-accent);
}

.main-nav {
  display: flex;
  align-items: center;
  gap: var(--space-8);
}

.nav-link {
  font-family: var(--font-body);
  font-size: var(--text-sm);
  font-weight: 500;
  color: var(--color-text-primary);
  letter-spacing: var(--tracking-wide);
  text-transform: uppercase;
  padding: var(--space-2) 0;
  position: relative;
  transition: color var(--transition-fast);
}

.nav-link::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  width: 0;
  height: 2px;
  background: var(--color-accent);
  transition: width var(--transition-base);
}

.nav-link:hover {
  color: var(--color-primary);
}

.nav-link:hover::after {
  width: 100%;
}

.nav-link.has-dropdown {
  display: flex;
  align-items: center;
  gap: var(--space-1);
}

.nav-link .dropdown-icon {
  width: 16px;
  height: 16px;
  transition: transform var(--transition-fast);
}

.nav-link.has-dropdown[aria-expanded="true"] .dropdown-icon {
  transform: rotate(180deg);
}

/* --- Mega Menu --- */
.mega-menu {
  position: absolute;
  top: var(--header-height);
  left: 0;
  right: 0;
  background: #ffffff;
  border-bottom: 1px solid var(--color-border);
  box-shadow: var(--shadow-xl);
  opacity: 0;
  visibility: hidden;
  transform: translateY(-8px);
  transition: opacity var(--transition-base), transform var(--transition-base), visibility var(--transition-base);
  z-index: 999;
}

.mega-menu.active {
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
}

.mega-menu-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-16);
  padding: var(--space-10) var(--space-6);
  max-width: var(--container-max);
  margin: 0 auto;
}

.mega-menu-column h4 {
  font-family: var(--font-body);
  font-size: var(--text-xs);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: var(--tracking-wider);
  color: var(--color-text-muted);
  margin-bottom: var(--space-6);
  padding-bottom: var(--space-3);
  border-bottom: 1px solid var(--color-border-light);
}

.mega-menu-list {
  display: grid;
  gap: var(--space-1);
}

.mega-menu-list a {
  display: block;
  padding: var(--space-3) var(--space-4);
  font-size: var(--text-sm);
  font-weight: 500;
  color: var(--color-text-primary);
  border-radius: var(--radius-md);
  transition: background var(--transition-fast), color var(--transition-fast);
}

.mega-menu-list a:hover {
  background: var(--color-bg-secondary);
  color: var(--color-primary);
}

/* --- Mobile Menu --- */
.mobile-menu-btn {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: var(--space-2);
  background: none;
  border: none;
  cursor: pointer;
}

.mobile-menu-btn span {
  display: block;
  width: 24px;
  height: 2px;
  background: var(--color-text-primary);
  transition: transform var(--transition-fast), opacity var(--transition-fast);
}

.mobile-menu-btn[aria-expanded="true"] span:nth-child(1) {
  transform: translateY(7px) rotate(45deg);
}

.mobile-menu-btn[aria-expanded="true"] span:nth-child(2) {
  opacity: 0;
}

.mobile-menu-btn[aria-expanded="true"] span:nth-child(3) {
  transform: translateY(-7px) rotate(-45deg);
}

.mobile-nav {
  display: none;
  position: fixed;
  top: var(--header-height);
  left: 0;
  right: 0;
  bottom: 0;
  background: #ffffff;
  z-index: 998;
  overflow-y: auto;
  padding: var(--space-6);
}

.mobile-nav.active {
  display: block;
}

.mobile-nav-list {
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
}

.mobile-nav-item {
  border-bottom: 1px solid var(--color-border-light);
}

.mobile-nav-link {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--space-4) 0;
  font-size: var(--text-lg);
  font-weight: 500;
  color: var(--color-text-primary);
}

.mobile-accordion-content {
  display: none;
  padding-bottom: var(--space-4);
  padding-left: var(--space-4);
}

.mobile-accordion-content.active {
  display: block;
}

.mobile-accordion-content a {
  display: block;
  padding: var(--space-3) 0;
  font-size: var(--text-base);
  color: var(--color-text-secondary);
}

.mobile-accordion-content a:hover {
  color: var(--color-primary);
}

.accordion-icon {
  width: 20px;
  height: 20px;
  transition: transform var(--transition-fast);
}

.mobile-nav-link[aria-expanded="true"] .accordion-icon {
  transform: rotate(180deg);
}

/* ============================================
   Buttons
   ============================================ */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-2);
  font-family: var(--font-body);
  font-size: var(--text-sm);
  font-weight: 600;
  letter-spacing: var(--tracking-wide);
  text-transform: uppercase;
  padding: var(--space-3) var(--space-6);
  border-radius: var(--radius-sm);
  transition: all var(--transition-fast);
  cursor: pointer;
  white-space: nowrap;
}

.btn-primary {
  background: var(--color-accent);
  color: var(--color-green-900);
}

.btn-primary:hover {
  background: var(--color-accent-hover);
  transform: translateY(-1px);
  box-shadow: var(--shadow-md);
}

.btn-secondary {
  background: transparent;
  color: var(--color-text-inverse);
  border: 1px solid rgba(255,255,255,0.4);
}

.btn-secondary:hover {
  background: rgba(255,255,255,0.1);
  border-color: rgba(255,255,255,0.6);
}

.btn-outline {
  background: transparent;
  color: var(--color-primary);
  border: 1px solid var(--color-primary);
}

.btn-outline:hover {
  background: var(--color-primary);
  color: var(--color-text-inverse);
}

.btn-dark {
  background: var(--color-primary);
  color: var(--color-text-inverse);
}

.btn-dark:hover {
  background: var(--color-primary-dark);
}

.btn-sm {
  padding: var(--space-2) var(--space-4);
  font-size: var(--text-xs);
}

.btn-lg {
  padding: var(--space-4) var(--space-8);
  font-size: var(--text-base);
}

/* ============================================
   Hero
   ============================================ */
.hero {
  position: relative;
  min-height: 85vh;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
}

.hero-bg {
  position: absolute;
  inset: 0;
  z-index: 0;
}

.hero-bg img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.hero-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    180deg,
    oklch(18% 0.04 165 / 0.75) 0%,
    oklch(14% 0.03 195 / 0.85) 100%
  );
  z-index: 1;
}

.hero-content {
  position: relative;
  z-index: 2;
  text-align: center;
  max-width: 800px;
  padding: var(--space-12) var(--space-6);
}

.hero-label {
  display: inline-block;
  font-size: var(--text-xs);
  font-weight: 600;
  letter-spacing: var(--tracking-wider);
  text-transform: uppercase;
  color: var(--color-accent);
  margin-bottom: var(--space-6);
}

.hero-title {
  font-size: var(--text-6xl);
  color: #ffffff;
  margin-bottom: var(--space-6);
  text-wrap: balance;
}

.hero-subtitle {
  font-size: var(--text-xl);
  color: oklch(90% 0.02 250);
  margin-bottom: var(--space-10);
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
  text-wrap: pretty;
}

.hero-actions {
  display: flex;
  gap: var(--space-4);
  justify-content: center;
  flex-wrap: wrap;
}

/* ============================================
   Cards
   ============================================ */
.card {
  background: var(--color-bg-primary);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: box-shadow var(--transition-base), transform var(--transition-base);
}

.card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-2px);
}

.card-image {
  width: 100%;
  aspect-ratio: 16 / 9;
  object-fit: cover;
}

.card-body {
  padding: var(--space-6);
}

.card-tag {
  display: inline-block;
  font-size: var(--text-xs);
  font-weight: 600;
  letter-spacing: var(--tracking-wider);
  text-transform: uppercase;
  color: var(--color-primary);
  margin-bottom: var(--space-3);
}

.card-title {
  font-family: var(--font-heading);
  font-size: var(--text-xl);
  margin-bottom: var(--space-3);
  line-height: var(--leading-snug);
}

.card-text {
  font-size: var(--text-sm);
  color: var(--color-text-secondary);
  margin-bottom: var(--space-4);
}

.card-link {
  display: inline-flex;
  align-items: center;
  gap: var(--space-2);
  font-size: var(--text-sm);
  font-weight: 600;
  color: var(--color-primary);
  transition: gap var(--transition-fast);
}

.card-link:hover {
  gap: var(--space-3);
}

/* ============================================
   Section Headers
   ============================================ */
.section-header {
  text-align: center;
  max-width: 700px;
  margin: 0 auto var(--space-16);
}

.section-header-left {
  text-align: left;
  margin-left: 0;
}

.section-label {
  display: inline-block;
  font-size: var(--text-xs);
  font-weight: 600;
  letter-spacing: var(--tracking-wider);
  text-transform: uppercase;
  color: var(--color-accent);
  margin-bottom: var(--space-4);
}

.section-title {
  margin-bottom: var(--space-6);
  text-wrap: balance;
}

.section-subtitle {
  font-size: var(--text-lg);
  color: var(--color-text-secondary);
  text-wrap: pretty;
}

/* ============================================
   Grids
   ============================================ */
.grid-2 {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--space-8);
}

.grid-3 {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-8);
}

.grid-4 {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--space-6);
}

.grid-6 {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-8);
}

/* ============================================
   Dark Section
   ============================================ */
.section-dark {
  background: var(--color-bg-dark);
  color: var(--color-text-inverse);
}

.section-dark h1,
.section-dark h2,
.section-dark h3,
.section-dark h4,
.section-dark h5,
.section-dark h6 {
  color: #ffffff;
}

.section-dark p {
  color: oklch(85% 0.02 250);
}

/* ============================================
   Announcement Banner
   ============================================ */
.announcement-banner {
  background: var(--color-bg-dark-alt);
  color: var(--color-text-inverse);
  padding: var(--space-4) 0;
}

.announcement-banner-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-6);
  flex-wrap: wrap;
}

.announcement-banner p {
  color: oklch(90% 0.02 250);
  font-size: var(--text-base);
  font-weight: 500;
}

/* ============================================
   Tabs (What We Do)
   ============================================ */
.tabs-vertical {
  display: grid;
  grid-template-columns: 280px 1fr;
  gap: var(--space-12);
  align-items: start;
}

.tabs-nav {
  display: flex;
  flex-direction: column;
  border-left: 2px solid var(--color-border);
}

.tab-btn {
  padding: var(--space-5) var(--space-6);
  font-family: var(--font-body);
  font-size: var(--text-base);
  font-weight: 500;
  color: var(--color-text-muted);
  text-align: left;
  border-left: 2px solid transparent;
  margin-left: -2px;
  transition: all var(--transition-fast);
  background: none;
  cursor: pointer;
}

.tab-btn:hover {
  color: var(--color-text-primary);
  background: var(--color-bg-secondary);
}

.tab-btn.active {
  color: var(--color-primary);
  border-left-color: var(--color-accent);
  background: var(--color-bg-secondary);
}

.tab-panel {
  display: none;
  animation: fadeIn 0.4s ease;
}

.tab-panel.active {
  display: block;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateX(12px); }
  to { opacity: 1; transform: translateX(0); }
}

.tab-panel h3 {
  margin-bottom: var(--space-4);
}

.tab-panel p {
  margin-bottom: var(--space-8);
  font-size: var(--text-lg);
}

/* ============================================
   Newsletter
   ============================================ */
.newsletter-form {
  display: flex;
  gap: var(--space-3);
  max-width: 480px;
  margin: var(--space-8) auto 0;
}

.newsletter-form input {
  flex: 1;
  padding: var(--space-3) var(--space-4);
  font-family: inherit;
  font-size: var(--text-base);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  background: var(--color-bg-primary);
  color: var(--color-text-primary);
}

.newsletter-form input:focus {
  outline: none;
  border-color: var(--color-primary);
  box-shadow: 0 0 0 3px oklch(50% 0.12 165 / 0.15);
}

/* ============================================
   Footer
   ============================================ */
.site-footer {
  background: var(--color-bg-dark);
  color: oklch(80% 0.02 250);
  padding-top: var(--space-20);
  padding-bottom: var(--space-10);
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr repeat(3, 1fr);
  gap: var(--space-12);
  margin-bottom: var(--space-16);
}

.footer-brand .logo {
  color: #ffffff;
  margin-bottom: var(--space-4);
}

.footer-brand p {
  color: oklch(75% 0.02 250);
  font-size: var(--text-sm);
  max-width: 280px;
}

.footer-column h5 {
  font-family: var(--font-body);
  font-size: var(--text-xs);
  font-weight: 600;
  letter-spacing: var(--tracking-wider);
  text-transform: uppercase;
  color: #ffffff;
  margin-bottom: var(--space-6);
}

.footer-column a {
  display: block;
  font-size: var(--text-sm);
  color: oklch(75% 0.02 250);
  padding: var(--space-2) 0;
  transition: color var(--transition-fast);
}

.footer-column a:hover {
  color: #ffffff;
}

.footer-bottom {
  border-top: 1px solid oklch(30% 0.03 195);
  padding-top: var(--space-8);
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: var(--space-4);
}

.footer-bottom p {
  font-size: var(--text-xs);
  color: oklch(65% 0.02 250);
}

.footer-legal {
  display: flex;
  gap: var(--space-6);
  flex-wrap: wrap;
}

.footer-legal a {
  font-size: var(--text-xs);
  color: oklch(65% 0.02 250);
}

.footer-legal a:hover {
  color: #ffffff;
}

/* ============================================
   Service Cards (Large)
   ============================================ */
.service-card {
  padding: var(--space-8);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  background: var(--color-bg-primary);
  transition: all var(--transition-base);
}

.service-card:hover {
  border-color: var(--color-primary);
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
}

.service-card h3 {
  font-size: var(--text-xl);
  margin-bottom: var(--space-3);
}

.service-card p {
  font-size: var(--text-sm);
  margin-bottom: var(--space-6);
}

/* ============================================
   Capability Cards
   ============================================ */
.capability-card {
  padding: var(--space-8);
  background: var(--color-bg-secondary);
  border-radius: var(--radius-lg);
  border: 1px solid var(--color-border-light);
  transition: all var(--transition-base);
}

.capability-card:hover {
  background: var(--color-bg-primary);
  border-color: var(--color-border);
  box-shadow: var(--shadow-md);
}

.capability-card h4 {
  font-family: var(--font-heading);
  font-size: var(--text-xl);
  margin-bottom: var(--space-3);
}

.capability-card p {
  font-size: var(--text-sm);
  margin-bottom: var(--space-4);
}

/* ============================================
   Commitment Cards
   ============================================ */
.commitment-card {
  padding: var(--space-8);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  background: var(--color-bg-primary);
  transition: all var(--transition-base);
}

.commitment-card:hover {
  border-color: var(--color-accent);
  box-shadow: var(--shadow-md);
}

.commitment-card h4 {
  font-size: var(--text-xl);
  margin-bottom: var(--space-3);
}

.commitment-card p {
  font-size: var(--text-sm);
  margin-bottom: var(--space-4);
}

/* ============================================
   Insight Cards (Compact)
   ============================================ */
.insight-card {
  display: grid;
  grid-template-columns: 120px 1fr;
  gap: var(--space-6);
  align-items: start;
  padding: var(--space-6);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  background: var(--color-bg-primary);
  transition: all var(--transition-base);
}

.insight-card:hover {
  border-color: var(--color-primary);
  box-shadow: var(--shadow-md);
}

.insight-card-image {
  width: 120px;
  height: 120px;
  object-fit: cover;
  border-radius: var(--radius-md);
}

.insight-card-content {
  display: flex;
  flex-direction: column;
  justify-content: center;
  min-height: 120px;
}

.insight-card-tag {
  font-size: var(--text-xs);
  font-weight: 600;
  letter-spacing: var(--tracking-wider);
  text-transform: uppercase;
  color: var(--color-primary);
  margin-bottom: var(--space-2);
}

.insight-card-title {
  font-family: var(--font-heading);
  font-size: var(--text-lg);
  margin-bottom: var(--space-2);
  line-height: var(--leading-snug);
}

.insight-card-date {
  font-size: var(--text-xs);
  color: var(--color-text-muted);
}

/* ============================================
   Carousel
   ============================================ */
.carousel {
  position: relative;
  overflow: hidden;
}

.carousel-track {
  display: flex;
  transition: transform var(--transition-slow);
}

.carousel-slide {
  min-width: 100%;
  padding: var(--space-4);
}

.carousel-controls {
  display: flex;
  gap: var(--space-3);
  justify-content: center;
  margin-top: var(--space-6);
}

.carousel-btn {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  border: 1px solid var(--color-border);
  background: var(--color-bg-primary);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--transition-fast);
}

.carousel-btn:hover {
  background: var(--color-primary);
  border-color: var(--color-primary);
  color: #ffffff;
}

.carousel-dots {
  display: flex;
  gap: var(--space-2);
  justify-content: center;
  margin-top: var(--space-4);
}

.carousel-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--color-border);
  border: none;
  cursor: pointer;
  transition: background var(--transition-fast);
}

.carousel-dot.active {
  background: var(--color-primary);
}

/* ============================================
   Testimonial
   ============================================ */
.testimonial {
  text-align: center;
  max-width: 800px;
  margin: 0 auto;
  padding: var(--space-12) var(--space-6);
}

.testimonial blockquote {
  font-family: var(--font-heading);
  font-size: var(--text-2xl);
  line-height: var(--leading-snug);
  color: var(--color-text-primary);
  margin-bottom: var(--space-8);
  font-style: italic;
}

.testimonial cite {
  font-family: var(--font-body);
  font-size: var(--text-sm);
  font-style: normal;
  font-weight: 600;
  color: var(--color-text-secondary);
}

/* ============================================
   Topic Tags
   ============================================ */
.topic-list {
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
}

.topic-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--space-4) var(--space-5);
  background: var(--color-bg-secondary);
  border-radius: var(--radius-md);
  font-size: var(--text-sm);
  font-weight: 500;
  color: var(--color-text-primary);
  transition: all var(--transition-fast);
}

.topic-item:hover {
  background: var(--color-primary);
  color: #ffffff;
}

/* ============================================
   Featured Insights (Homepage strip)
   ============================================ */
.featured-strip {
  background: var(--color-bg-secondary);
  padding: var(--space-8) 0;
}

.featured-strip-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-8);
}

.featured-strip-item {
  padding: var(--space-4);
}

.featured-strip-item h4 {
  font-family: var(--font-body);
  font-size: var(--text-xs);
  font-weight: 600;
  letter-spacing: var(--tracking-wider);
  text-transform: uppercase;
  color: var(--color-accent);
  margin-bottom: var(--space-3);
}

.featured-strip-item p {
  font-size: var(--text-base);
  font-weight: 500;
  color: var(--color-text-primary);
  line-height: var(--leading-snug);
}

/* ============================================
   Responsive
   ============================================ */
@media (max-width: 1024px) {
  .grid-4 {
    grid-template-columns: repeat(2, 1fr);
  }

  .grid-6 {
    grid-template-columns: repeat(2, 1fr);
  }

  .tabs-vertical {
    grid-template-columns: 1fr;
  }

  .tabs-nav {
    flex-direction: row;
    border-left: none;
    border-bottom: 2px solid var(--color-border);
    overflow-x: auto;
  }

  .tab-btn {
    border-left: none;
    border-bottom: 2px solid transparent;
    margin-left: 0;
    margin-bottom: -2px;
    white-space: nowrap;
  }

  .tab-btn.active {
    border-left-color: transparent;
    border-bottom-color: var(--color-accent);
  }

  .footer-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .mega-menu-inner {
    grid-template-columns: 1fr;
    gap: var(--space-8);
  }
}

@media (max-width: 768px) {
  :root {
    --header-height: 64px;
  }

  .main-nav {
    display: none;
  }

  .mobile-menu-btn {
    display: flex;
  }

  .grid-2,
  .grid-3,
  .grid-4,
  .grid-6 {
    grid-template-columns: 1fr;
  }

  .featured-strip-grid {
    grid-template-columns: 1fr;
  }

  .footer-grid {
    grid-template-columns: 1fr;
    gap: var(--space-8);
  }

  .footer-bottom {
    flex-direction: column;
    text-align: center;
  }

  .hero-title {
    font-size: var(--text-4xl);
  }

  .insight-card {
    grid-template-columns: 1fr;
  }

  .insight-card-image {
    width: 100%;
    height: 180px;
  }

  .announcement-banner-inner {
    flex-direction: column;
    text-align: center;
  }

  .newsletter-form {
    flex-direction: column;
  }

  .section {
    padding-top: var(--space-16);
    padding-bottom: var(--space-16);
  }
}

/* ============================================
   Utility Classes
   ============================================ */
.text-center { text-align: center; }
.text-left { text-align: left; }
.text-right { text-align: right; }

.mt-4 { margin-top: var(--space-4); }
.mt-6 { margin-top: var(--space-6); }
.mt-8 { margin-top: var(--space-8); }
.mt-12 { margin-top: var(--space-12); }

.mb-4 { margin-bottom: var(--space-4); }
.mb-6 { margin-bottom: var(--space-6); }
.mb-8 { margin-bottom: var(--space-8); }
.mb-12 { margin-bottom: var(--space-12); }

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}
